const body = $input.first().json.body || $input.first().json;
const message = body.message || body;
const call = message.call || body.call || {};
const type = message.type || body.type || 'unknown';
const status = (call.status || message.status || '').toLowerCase();
const isEnd = /end|completed|report|analysis/i.test(String(type)) || status === 'ended' || status === 'completed';

const transcript =
  message.transcript ||
  call.transcript ||
  message.artifact?.transcript ||
  (Array.isArray(message.messages)
    ? message.messages.map(m => `${m.role || 'x'}: ${m.message || m.content || ''}`).join('\n')
    : '');

const summary =
  message.analysis?.summary ||
  message.summary ||
  (transcript ? transcript.slice(0, 400) : 'Call finished');

let interestScore = 40;
if (/interested|budget|looking|buy|rent/i.test(transcript)) interestScore += 25;
if (/not interested|busy|no thanks/i.test(transcript)) interestScore -= 20;
interestScore = Math.max(0, Math.min(100, interestScore));

const interestLevel = interestScore >= 75 ? 'HIGH' : interestScore >= 50 ? 'MEDIUM' : interestScore >= 25 ? 'LOW' : 'NONE';
const leadStatus = interestScore >= 75 ? 'INTERESTED' : interestScore >= 50 ? 'FOLLOW_UP' : interestScore >= 25 ? 'PENDING' : 'NOT_INTERESTED';

return [{
  json: {
    shouldWrite: isEnd || Boolean(call.id),
    vapiCallId: call.id || message.callId,
    status: isEnd ? 'COMPLETED' : (status || 'IN_PROGRESS'),
    durationSeconds: call.duration || message.duration || undefined,
    recordingUrl: call.recordingUrl || message.artifact?.recordingUrl,
    transcript,
    summary,
    interestScore,
    interestLevel,
    leadStatus,
    recommendedAction: interestScore >= 50 ? 'Human follow-up with matching listings' : 'Nurture later',
    rawPayload: body,
  }
}];
